import React from 'react';
import Slider from 'react-slick';
import { Box, Card, CardContent, CardMedia, Typography } from '@mui/material';
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

function EventsSlider() {
    // Örnek veri
    const events = [
        {
            id: 1,
            title: "Tech Summit 2024",
            image: "https://picsum.photos/800/400",
            date: "15 Nisan 2024",
            location: "İstanbul"
        },
        {
            id: 2,
            title: "Web Development Workshop",
            image: "https://picsum.photos/800/400",
            date: "20 Nisan 2024",
            location: "Ankara"
        },
        {
            id: 3,
            title: "AI Conference",
            image: "https://picsum.photos/800/400",
            date: "25 Nisan 2024",
            location: "İzmir"
        },
        // Daha fazla etkinlik ekleyebilirsiniz
    ];

    // Slider ayarları
    const settings = {
        dots: true,
        infinite: true,
        speed: 500,
        slidesToShow: 3,
        slidesToScroll: 1,
        autoplay: true,
        autoplaySpeed: 3000,
        responsive: [
            {
                breakpoint: 1024,
                settings: {
                    slidesToShow: 2,
                }
            },
            {
                breakpoint: 600,
                settings: {
                    slidesToShow: 1,
                }
            }
        ]
    };

    return (
        <Box sx={{ 
            maxWidth: '1200px', 
            margin: '0 auto', 
            padding: '20px',
            '.slick-slide': {
                padding: '0 10px'
            }
        }}>
            <Slider {...settings}>
                {events.map((event) => (
                    <Box key={event.id}>
                        <Card sx={{ 
                            maxWidth: '100%',
                            height: '100%',
                            boxShadow: '0 4px 8px rgba(0,0,0,0.1)',
                            '&:hover': {
                                transform: 'translateY(-5px)',
                                transition: 'transform 0.3s ease-in-out'
                            }
                        }}>
                            <CardMedia
                                component="img"
                                height="200"
                                image={event.image}
                                alt={event.title}
                            />
                            <CardContent>
                                <Typography gutterBottom variant="h6" component="div">
                                    {event.title}
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                    {event.date}
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                    {event.location}
                                </Typography>
                            </CardContent>
                        </Card>
                    </Box>
                ))}
            </Slider>
        </Box>
    );
}

export default EventsSlider;
